<script setup lang="ts">
import StudioMetrics from './StudioMetrics.vue'
import {computed,onMounted,ref} from 'vue'
import {api} from './api'
import CourseDurationStats from './CourseDurationStats.vue'
import VisitorTraffic from './VisitorTraffic.vue'
const access=ref<boolean|null>(null),busy=ref(false),error=ref(''),tab=ref('overview'),overview=ref<any>(null),feedback=ref<any>({rows:[],total:0}),tasks=ref<any>({rows:[],total:0}),options=ref<any>({users:[],courses:[],languages:{},domains:{},durationBuckets:{},audiences:{}})
const filters=ref({start:'',end:'',userId:'',taskId:'',language:'',domain:'',durationBucket:'',mode:'',q:'',includeTests:false,rating:'',category:[] as string[],feedbackStatus:'',taskStatus:''})
const traffic=ref<any>(null)
const page=ref(1),pageSize=30,selectedUser=ref<any>(null),edit=ref<any>(null),saving=ref(false),exporting=ref(false)
const categories:Record<string,string>={translation:'翻译',narration:'讲稿',speech:'语音',avatar:'数字人',subtitles:'字幕',layout:'排版',performance:'速度或任务处理',account:'账号或使用问题',other:'其他'}
const statusNames:Record<string,string>={new:'待查看',reviewing:'查看中',planned:'计划改进',resolved:'已处理',completed:'已完成',failed:'失败',cancelled:'已取消',processing:'生成中',queued:'排队中',waiting_input:'等待素材'}
const visibleCourses=computed(()=>options.value.courses.filter((c:any)=>(filters.value.includeTests||!c.isTest)&&(!filters.value.userId||c.userId===filters.value.userId)))
const userChoices=computed(()=>options.value.users.filter((u:any)=>filters.value.includeTests||!u.isTest))
const distributions=computed(()=>overview.value?[['目标语种分布','targetLanguages'],['输入语种分布','sourceLanguages'],['课程领域','domains'],['面向人群','audiences'],['主题标签偏好','topics'],['创建方式','modes'],['任务状态','statuses']]:[])
function query(section:string,p=page.value){const q=new URLSearchParams();for(const [key,value] of Object.entries(filters.value)){if(section==='traffic'&&!['start','end','userId','includeTests'].includes(key))continue;if(['rating','category','feedbackStatus'].includes(key)&&section!=='feedback')continue;if(key==='taskStatus'&&section!=='tasks')continue;if(key==='includeTests'){if(value)q.set(key,'1')}else if(Array.isArray(value)){if(value.length)q.set(key,value.join(','))}else if(value)q.set(key,String(value))}q.set('page',String(p));q.set('pageSize',String(pageSize));return q.toString()}
let requestId=0
async function refresh(reset=false){if(reset)page.value=1;const id=++requestId;busy.value=true;error.value='';try{const section=tab.value==='feedback'?'feedback':tab.value==='tasks'?'tasks':tab.value==='traffic'?'traffic':'overview';const result=await api<any>('/v1/admin/'+section+'?'+query(section));if(id!==requestId)return;if(section==='feedback')feedback.value=result;else if(section==='tasks')tasks.value=result;else if(section==='traffic')traffic.value=result;else overview.value=result}catch(e){if(id===requestId)error.value=(e as Error).message}finally{if(id===requestId)busy.value=false}}
async function changeTab(value:any){tab.value=String(value);await refresh(true)}
function resetFilters(){filters.value={start:'',end:'',userId:'',taskId:'',language:'',domain:'',durationBucket:'',mode:'',q:'',includeTests:false,rating:'',category:[],feedbackStatus:'',taskStatus:''};void refresh(true)}
function seconds(value:any){if(value===null||value===undefined)return '未记录';return value>=60?(value/60).toFixed(1)+' 分':Number(value).toFixed(1)+' 秒'}
function date(value:any){return value?new Date(value).toLocaleString():'未记录'}
function pct(value:any){return value===null||value===undefined?'—':value+'%'}
function languageText(values:string[]){return values.map(v=>options.value.languages[v]||v).join('、')}
function drillUser(user:any){filters.value.userId=user.id;filters.value.taskId='';selectedUser.value=null;void refresh(true)}
async function saveFeedback(){if(!edit.value)return;saving.value=true;try{await api('/v1/admin/feedback/'+edit.value.id,{method:'PUT',body:JSON.stringify({status:edit.value.status,adminNote:edit.value.adminNote||''})});edit.value=null;await refresh()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function exportData(){exporting.value=true;error.value='';try{let result:any;if(tab.value==='feedback'||tab.value==='tasks'){const section=tab.value;const rows:any[]=[];for(let p=1;;p++){const part=await api<any>('/v1/admin/'+section+'?'+query(section,p));rows.push(...part.rows);if(rows.length>=part.total||!part.rows.length)break}result={filters:filters.value,rows}}else result={filters:filters.value,...(tab.value==='traffic'?traffic.value:overview.value)};const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='smartcourse-'+tab.value+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url)}catch(e){error.value=(e as Error).message}finally{exporting.value=false}}
onMounted(async()=>{try{const result=await api<any>('/v1/admin/access');access.value=result.isAdmin;if(access.value){options.value=await api('/v1/admin/options');await refresh(true)}}catch(e){access.value=false;error.value=(e as Error).message}})
</script>
<template>
 <div class="admin-console">
  <header class="admin-heading"><div><p>OPERATIONS CONSOLE</p><h1>管理后台</h1><span>统一查看课程反馈、用户使用情况与生成表现</span></div><el-button v-if="access" :loading="exporting" @click="exportData">导出当前数据</el-button></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <el-skeleton v-if="access===null" :rows="4" animated/>
  <el-result v-else-if="!access" icon="warning" title="需要管理员权限" sub-title="普通账号只能查看自己的课程和反馈。请联系项目负责人开通管理权限。"/>
  <template v-else>
   <StudioMetrics/><section class="admin-panel filters"><el-form label-position="top"><div class="filter-grid">
    <el-form-item label="起始日期"><el-input v-model="filters.start" type="date"/></el-form-item><el-form-item label="结束日期"><el-input v-model="filters.end" type="date"/></el-form-item>
    <el-form-item label="用户"><el-select v-model="filters.userId" clearable filterable @change="filters.taskId=''">
     <el-option v-for="user in userChoices" :key="user.id" :value="user.id" :label="user.name+' · '+user.account"/>
    </el-select></el-form-item><el-form-item v-show="tab!=='traffic'" label="课程"><el-select v-model="filters.taskId" clearable filterable><el-option v-for="course in visibleCourses" :key="course.id" :value="course.id" :label="course.name+' · '+course.id"/></el-select></el-form-item>
    <el-form-item v-show="tab!=='traffic'" label="目标语种"><el-select v-model="filters.language" clearable><el-option v-for="(label,key) in options.languages" :key="key" :value="key" :label="label"/></el-select></el-form-item>
    <el-form-item v-show="tab!=='traffic'" label="创建方式"><el-select v-model="filters.mode" clearable><el-option value="upload" label="已有课件"/><el-option value="topic" label="主题课程"/><el-option value="code" label="代码课程"/></el-select></el-form-item>
    <el-form-item v-show="tab!=='traffic'" label="课程领域"><el-select v-model="filters.domain" clearable><el-option v-for="(label,key) in options.domains" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item v-show="tab!=='traffic'" label="MOOC 课程时长"><el-select v-model="filters.durationBucket" clearable><el-option v-for="(label,key) in options.durationBuckets" :key="key" :value="key" :label="label"/></el-select></el-form-item>
    <el-form-item v-show="tab!=='traffic'" label="课程名称或主题搜索"><el-input v-model="filters.q" clearable placeholder="课程名、主题、编号" @keyup.enter="refresh(true)"/></el-form-item>
    <template v-if="tab==='feedback'"><el-form-item label="评分"><el-select v-model="filters.rating" clearable><el-option v-for="score in 5" :key="score" :label="score+' 分'" :value="String(score)"/><el-option value="unrated" label="未评分"/></el-select></el-form-item><el-form-item label="问题类型（可多选，匹配任一）"><el-select v-model="filters.category" multiple collapse-tags clearable><el-option v-for="(label,key) in categories" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="处理状态"><el-select v-model="filters.feedbackStatus" clearable><el-option v-for="key in ['new','reviewing','planned','resolved']" :key="key" :label="statusNames[key]" :value="key"/></el-select></el-form-item></template>
    <el-form-item v-if="tab==='tasks'" label="任务状态"><el-select v-model="filters.taskStatus" clearable><el-option v-for="key in ['completed','failed','processing','queued','cancelled','waiting_input']" :key="key" :label="statusNames[key]" :value="key"/></el-select></el-form-item>
   </div><div class="filter-actions"><el-checkbox v-model="filters.includeTests">包含测试账号和部署自检</el-checkbox><span>日期按北京时间；反馈按提交时间，课程统计按创建时间筛选。</span><el-button @click="resetFilters">重置</el-button><el-button type="primary" :loading="busy" @click="refresh(true)">查询</el-button></div></el-form></section>
   <el-tabs :model-value="tab" @tab-change="changeTab"><el-tab-pane label="使用概览" name="overview"/><el-tab-pane label="全部评分与反馈" name="feedback"/><el-tab-pane label="用户使用明细" name="users"/><el-tab-pane label="课程与阶段明细" name="tasks"/><el-tab-pane label="访问 IP 与地域" name="traffic"/></el-tabs>
   <div v-loading="busy">
    <VisitorTraffic v-if="tab==='traffic'&&traffic" :value="traffic"/>
    <template v-if="tab==='overview'&&overview">
     <section class="stat-grid"><article v-for="[label,key] in [['用户数','users'],['活跃用户','activeUsers'],['新注册用户','newUsers'],['课程任务','tasks'],['已完成','completed'],['失败','failed'],['输入课件页数','inputPages'],['生成语音分钟','outputMinutes'],['重新执行次数','reexecutionCount'],['登录次数','logins'],['结果播放次数','plays'],['下载点击次数','downloads'],['示例选用次数','exampleSelections']]" :key="key"><b>{{overview.summary[key]}}</b><span>{{label}}</span></article><article><b>{{pct(overview.summary.completionRate)}}</b><span>课程完成比例</span></article></section>
     <p class="data-note">行为记录启用时间：{{date(overview.trackingSince)}}。没有历史记录的数据不会补算成实际使用。</p>
     <div class="charts-grid"><section v-for="[title,key] in distributions" :key="key" class="admin-panel distribution"><h3>{{title}}</h3><p v-if="!overview[key]?.length" class="empty-note">暂无数据</p><div v-for="row in overview[key]" :key="row.key" class="bar-row"><span :title="row.label">{{row.label}}</span><div><i :style="{width:row.percent+'%'}"></i></div><b>{{row.count}}</b><small>{{row.percent}}%</small></div></section></div>
     <section class="admin-panel"><CourseDurationStats :value="overview.courseDuration"/></section>
     <section class="admin-panel"><h3>各语种课程时长</h3><el-table :data="overview.durationByLanguage" stripe><el-table-column prop="label" label="语种"/><el-table-column prop="generatedVersions" label="已生成版本"/><el-table-column prop="samples" label="时长样本"/><el-table-column label="总播放时长"><template #default="s">{{seconds(s.row.totalSeconds)}}</template></el-table-column><el-table-column label="平均时长"><template #default="s">{{seconds(s.row.averageSeconds)}}</template></el-table-column><el-table-column label="中位数"><template #default="s">{{seconds(s.row.medianSeconds)}}</template></el-table-column><el-table-column label="最长"><template #default="s">{{seconds(s.row.maximumSeconds)}}</template></el-table-column></el-table></section>
     <section class="admin-panel"><h3>每天的课程使用</h3><el-table :data="overview.daily" stripe max-height="380"><el-table-column prop="date" label="日期"/><el-table-column prop="users" label="创建课程用户"/><el-table-column prop="tasks" label="任务数"/><el-table-column prop="completed" label="其中已完成"/></el-table></section>
     <section class="admin-panel"><h3>S1–S5 阶段耗时</h3><p class="data-note">统计最近一次完成或失败的阶段，包含样本数与失败数。排队状态、尚未执行及缺少耗时的阶段不按零计算。</p><el-table :data="overview.stageTimes" stripe><el-table-column prop="code" label="阶段"/><el-table-column prop="samples" label="耗时样本"/><el-table-column prop="completed" label="完成"/><el-table-column prop="failed" label="失败"/><el-table-column label="平均"><template #default="s">{{seconds(s.row.averageSeconds)}}</template></el-table-column><el-table-column label="中位数"><template #default="s">{{seconds(s.row.medianSeconds)}}</template></el-table-column><el-table-column label="P90"><template #default="s">{{seconds(s.row.p90Seconds)}}</template></el-table-column><el-table-column label="累计"><template #default="s">{{seconds(s.row.totalSeconds)}}</template></el-table-column><el-table-column label="平均资源等待"><template #default="s">{{seconds(s.row.queueWait?.averageSeconds)}}</template></el-table-column></el-table></section>
     <div class="charts-grid"><section class="admin-panel"><h3>课程名称与主题输入</h3><el-table :data="overview.courseNames" max-height="380"><el-table-column prop="label" label="名称或输入主题"/><el-table-column prop="count" label="次数" width="70"/></el-table></section><section class="admin-panel"><h3>失败说明</h3><el-table :data="overview.failureMessages" max-height="380"><el-table-column prop="label" label="说明"/><el-table-column prop="count" label="次数" width="70"/></el-table></section></div>
     <section class="admin-panel"><h3>统计说明</h3><ul><li v-for="note in overview.notes" :key="note">{{note}}</li></ul></section>
    </template>
    <template v-if="tab==='feedback'"><div class="stat-grid"><article><b>{{feedback.total}}</b><span>筛选后的反馈</span></article><article><b>{{feedback.averageRating??'—'}}</b><span>平均评分 / 5</span></article><article><b>{{feedback.ratedCount||0}}</b><span>有评分的记录</span></article><article><b>{{feedback.lowRatingCount||0}}</b><span>1–2 分记录</span></article></div><div class="charts-grid"><section class="admin-panel"><h3>问题类型分布</h3><div v-for="row in feedback.categoryDistribution||[]" :key="row.key" class="bar-row"><span>{{categories[row.key]||row.key}}</span><div><i :style="{width:row.percent+'%'}"></i></div><b>{{row.count}}</b><small>{{row.percent}}%</small></div></section><section class="admin-panel"><h3>各语种反馈与评分</h3><el-table :data="feedback.languageQuality||[]"><el-table-column prop="label" label="语种"/><el-table-column prop="feedbackCount" label="反馈数"/><el-table-column prop="ratedCount" label="评分数"/><el-table-column prop="averageRating" label="平均分"/><el-table-column prop="lowRatingCount" label="1–2 分"/></el-table></section></div><section class="admin-panel"><el-table :data="feedback.rows" stripe><el-table-column label="用户 / 课程" min-width="190"><template #default="s"><strong>{{s.row.userName}}</strong><p>{{s.row.account}}</p><p>{{s.row.taskName}}</p><small>{{s.row.taskId}}</small></template></el-table-column><el-table-column label="语种 / 评分" width="120"><template #default="s">{{options.languages[s.row.language]||'一般反馈'}}<p>{{s.row.rating?s.row.rating+' / 5':'未评分'}}</p><el-tag v-if="s.row.isTest" type="info">测试</el-tag></template></el-table-column><el-table-column label="反馈内容" min-width="280"><template #default="s"><div class="category-tags"><el-tag v-for="key in s.row.categories" :key="key" size="small">{{categories[key]||key}}</el-tag></div><p class="feedback-text">{{s.row.comment}}</p><small>{{s.row.page?'第 '+s.row.page+' 页 ':''}}{{s.row.playbackSeconds!==null?'视频 '+seconds(s.row.playbackSeconds):''}}</small><p v-if="s.row.adminNote">处理备注：{{s.row.adminNote}}</p></template></el-table-column><el-table-column label="状态 / 时间" min-width="150"><template #default="s">{{statusNames[s.row.status]||s.row.status}}<p>{{date(s.row.createdAt)}}</p></template></el-table-column><el-table-column label="操作" width="90"><template #default="s"><el-button link type="primary" @click="edit={...s.row}">处理</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="pageSize" :total="feedback.total" layout="prev,pager,next,total" @current-change="refresh()"/></section></template>
    <section v-if="tab==='users'&&overview" class="admin-panel"><p>点击用户查看语种、主题、阶段耗时和行为统计。点击“仅看此用户”可同步筛选其他页面。</p><el-table :data="overview.users" stripe @row-click="selectedUser=$event"><el-table-column label="用户" min-width="180"><template #default="s"><strong>{{s.row.name}}</strong><p>{{s.row.account}}</p><small>{{s.row.institution}}</small><el-tag v-if="s.row.isTest" size="small" type="info">测试</el-tag></template></el-table-column><el-table-column prop="tasks" label="任务" width="70"/><el-table-column prop="completed" label="完成" width="70"/><el-table-column prop="failed" label="失败" width="70"/><el-table-column label="视频总时长" min-width="110"><template #default="s">{{seconds(s.row.courseDuration.totalSeconds)}}</template></el-table-column><el-table-column prop="activeDays" label="活跃天数" width="90"/><el-table-column prop="logins" label="登录" width="70"/><el-table-column prop="plays" label="播放" width="70"/><el-table-column prop="downloads" label="下载" width="70"/><el-table-column prop="feedbackCount" label="反馈" width="70"/><el-table-column label="最近使用" min-width="150"><template #default="s">{{date(s.row.lastActive)}}</template></el-table-column></el-table></section>
    <section v-if="tab==='tasks'" class="admin-panel"><el-table :data="tasks.rows" stripe><el-table-column label="课程" min-width="210"><template #default="s"><strong>{{s.row.name}}</strong><p>{{s.row.id}}</p><small>{{s.row.userName}} · {{s.row.account}}</small><p>{{languageText(s.row.languages)}}</p></template></el-table-column><el-table-column label="状态" width="100"><template #default="s">{{statusNames[s.row.status]||s.row.status}}<p>{{s.row.pageCount??'—'}} 页</p></template></el-table-column><el-table-column label="课程视频时长" min-width="160"><template #default="s"><div v-for="version in s.row.courseVersions" :key="version.language">{{version.label}} · {{seconds(version.durationSeconds)}}</div><span v-if="!s.row.courseVersions?.length">尚未生成</span></template></el-table-column><el-table-column label="阶段耗时" min-width="260"><template #default="s"><div v-for="stage in s.row.stages" :key="stage.code">{{stage.code}} · {{statusNames[stage.status]||stage.status}} · {{seconds(stage.elapsedSeconds)}}</div></template></el-table-column><el-table-column label="主题 / 分类" min-width="180"><template #default="s"><p>{{s.row.topic}}</p><small>{{options.domains[s.row.profile.domain]||'领域未填写'}}</small></template></el-table-column><el-table-column label="创建时间 / 错误" min-width="160"><template #default="s">{{date(s.row.createdAt)}}<p>{{s.row.error?.message}}</p></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="pageSize" :total="tasks.total" layout="prev,pager,next,total" @current-change="refresh()"/></section>
   </div>
   <el-dialog :model-value="!!edit" title="处理反馈" width="min(620px,95vw)" @close="edit=null"><template v-if="edit"><p>{{edit.taskName}}</p><p class="feedback-text">{{edit.comment}}</p><el-form label-position="top"><el-form-item label="处理状态"><el-select v-model="edit.status"><el-option v-for="key in ['new','reviewing','planned','resolved']" :key="key" :value="key" :label="statusNames[key]"/></el-select></el-form-item><el-form-item label="管理备注"><el-input v-model="edit.adminNote" type="textarea" :rows="4" maxlength="4000"/></el-form-item></el-form><el-button type="primary" :loading="saving" @click="saveFeedback">保存处理记录</el-button></template></el-dialog>
   <el-dialog :model-value="!!selectedUser" title="用户使用明细" width="min(900px,96vw)" @close="selectedUser=null"><template v-if="selectedUser"><h3>{{selectedUser.name}} · {{selectedUser.account}}</h3><p>{{selectedUser.institution}} · 注册于 {{date(selectedUser.registeredAt)}}</p><p>课程 {{selectedUser.tasks}} · 完成 {{selectedUser.completed}} · 失败 {{selectedUser.failed}} · 活跃 {{selectedUser.activeDays}} 天 · 评分均值 {{selectedUser.averageRating??'未评分'}}</p><h4>目标语种</h4><p>{{selectedUser.languages.map((v:any)=>v.label+' '+v.count+' 次').join('、')||'未记录'}}</p><template v-for="[title,key] in [['课程领域','domains'],['面向人群','audiences']]" :key="key"><h4>{{title}}</h4><p>{{selectedUser[key]?.map((v:any)=>v.label+' '+v.count+' 次').join('、')||'未填写'}}</p></template><h4>主题标签</h4><p>{{selectedUser.topics.map((v:any)=>v.label+' '+v.count+' 次').join('、')||'未填写'}}</p><CourseDurationStats :value="selectedUser.courseDuration"/><h4>阶段耗时</h4><el-table :data="Object.entries(selectedUser.stageSeconds).map(([code,value])=>({code,...(value as any)}))"><el-table-column prop="code" label="阶段"/><el-table-column prop="samples" label="样本"/><el-table-column label="均值"><template #default="s">{{seconds(s.row.averageSeconds)}}</template></el-table-column><el-table-column label="累计"><template #default="s">{{seconds(s.row.totalSeconds)}}</template></el-table-column></el-table><el-button type="primary" @click="drillUser(selectedUser)">仅看此用户</el-button></template></el-dialog>
  </template>
 </div>
